/* Explicit campaign schedules. Existing campaigns remain manual until configured. */
(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,T=(en,ko)=>window.UKI18n?.language==='en'?en:ko;
const names={Occupation:'오큐페이션',Downtime:'다운타임',Takeover:'테이크오버','Phase 1':'1단계','Phase 2':'2단계','Phase 3':'3단계'};
function preset(edition,typeId){return String(edition).toUpperCase()==='N26'&&(!typeId||typeId==='official-003-campaign-necromunda-campaign')?(window.RULES_DATA?.campaignTypes||[]).find(r=>r.source_verified&&r.id==='official-003-campaign-necromunda-campaign')?.rule_data?.phases:null;}
const typeFor=c=>c.campaignTypeId||(typeof cpCampaignType==='function'?cpCampaignType(c)?.id:null)||'manual';
const positive=n=>/^[1-9]\d*$/.test(String(n??''))&&Number.isSafeInteger(Number(n));
const canEdit=c=>!!window.MMCampaignPermissions?.canArbitrate(c);
function valid(plan){return plan&&['standard','custom'].includes(plan.mode)&&Array.isArray(plan.stages)&&plan.stages.length>0&&plan.stages.every(s=>typeof s.name==='string'&&Number.isSafeInteger(s.cycles)&&s.cycles>0&&s.cycles<=999);}
function info(c){const plan=c?.campaignSchedule;const standard=preset(c.edition,typeFor(c));if(!valid(plan)||plan.mode==='standard'&&(!standard||plan.stages.length!==standard.length||plan.stages.some((s,i)=>s.name!==standard[i].name||s.cycles!==standard[i].cycles)))return null;const total=plan.stages.reduce((n,s)=>n+s.cycles,0),cycle=positive(c.currentCycle)?Number(c.currentCycle):1;let offset=0;for(const s of plan.stages){if(cycle<=offset+s.cycles)return {plan,total,cycle,stage:s,stageCycle:cycle-offset,complete:!!plan.completed};offset+=s.cycles;}return {plan,total,cycle,stage:plan.stages.at(-1),stageCycle:plan.stages.at(-1).cycles,complete:!!plan.completed,outOfRange:true};}
function fields(edition,typeId,c){const source=preset(edition,typeId||(c?typeFor(c):'')),saved=c?.campaignSchedule,mode=valid(saved)?saved.mode:source?'standard':'custom',defaults=source||[{name:'Phase 1',cycles:1},{name:'Phase 2',cycles:0},{name:'Phase 3',cycles:0}];return `<fieldset class="wide csp-fields" data-schedule-fields data-stage-names="${E(defaults.map(s=>s.name).join('|'))}"><legend>${L('Campaign progression','캠페인 진행 방식')}</legend><div class="csp-modes"><label class="checkline"><input type="radio" name="scheduleMode" value="standard" ${mode==='standard'?'checked':''} ${source?'':'disabled'}>${L('Standard structure (fixed)','일반 구성으로 고정')}</label><label class="checkline"><input type="radio" name="scheduleMode" value="custom" ${mode==='custom'?'checked':''}>${L('Custom cycle counts','커스텀 사이클 구성')}</label></div><p class="csp-hint">${source?L('Standard: Occupation 3 → Downtime 1 → Takeover 3. Custom changes each stage’s cycle count; 0 skips that stage. The organiser still sets calendar dates.','일반 구성: 오큐페이션 3 → 다운타임 1 → 테이크오버 3. 커스텀은 단계별 사이클 수를 정하며 0은 해당 단계를 건너뜁니다. 실제 날짜는 운영자가 정합니다.'):L('No verified standard schedule exists for this edition. These are manually chosen app stages, not rules from another edition.','이 판본에는 확인된 일반 일정이 없습니다. 다른 판본의 룰을 가져오지 않고 직접 정한 앱 진행 단계로 기록합니다.')}</p><div class="csp-stage-inputs">${defaults.map((s,i)=>{const old=saved?.stages?.find(x=>x.name===s.name),value=valid(saved)?old?.cycles??0:s.cycles;return `<label>${L(s.name,names[s.name]||`${i+1}단계`)}<input name="scheduleCycles${i}" type="number" min="0" max="999" step="1" inputmode="numeric" value="${mode==='standard'?s.cycles:value}" ${mode==='standard'?'readonly':''}></label>`;}).join('')}</div><p class="csp-total" aria-live="polite"></p></fieldset>`;}
function read(form,edition,typeId){const mode=form.elements.scheduleMode?.value,source=preset(edition,typeId),defaults=source||[{name:'Phase 1',cycles:1},{name:'Phase 2',cycles:0},{name:'Phase 3',cycles:0}];if(mode==='standard'&&!source||!['standard','custom'].includes(mode))return {error:T('Choose a supported progression mode.','사용 가능한 진행 방식을 선택하세요.')};const cycles=mode==='standard'?source.map(s=>s.cycles):defaults.map((_,i)=>String(form.elements['scheduleCycles'+i]?.value??''));if(cycles.some(v=>!/^\d+$/.test(String(v))||!Number.isSafeInteger(Number(v))||Number(v)<0||Number(v)>999)||cycles.every(v=>Number(v)===0))return {error:T('Use whole stage counts from 0 to 999, with at least one cycle in total.','단계별로 0~999 정수를 입력하고, 전체 사이클은 1 이상으로 설정하세요.')};return {value:{mode,stages:defaults.map((s,i)=>({name:s.name,cycles:Number(cycles[i])})).filter(s=>s.cycles>0),completed:false,history:[]}};}
function bind(form,getContext){let custom=null;function sync(){const {edition,typeId}=getContext(),source=preset(edition,typeId),box=form.querySelector('[data-schedule-fields]');if(!box)return;const standard=box.querySelector('[value=standard]');standard.disabled=!source;if(!source&&standard.checked)box.querySelector('[value=custom]').checked=true;const fixed=form.elements.scheduleMode.value==='standard';const values=[0,1,2].map(i=>form.elements['scheduleCycles'+i]);values.forEach((el,i)=>{el.readOnly=fixed;if(fixed&&source)el.value=source[i].cycles;});const checked=read(form,edition,typeId);box.querySelector('.csp-total').innerHTML=checked.error?L('Enter valid cycle counts.','사이클 수를 확인하세요.'):`${L('Total','전체')} ${checked.value.stages.reduce((n,s)=>n+s.cycles,0)} ${L('cycles','사이클')}`;}
 form.addEventListener('change',event=>{if(['edition','campaignType'].includes(event.target.name)){const {edition,typeId}=getContext(),oldBox=form.querySelector('[data-schedule-fields]'),oldNames=oldBox.dataset.stageNames,oldMode=form.elements.scheduleMode.value,oldValues=[0,1,2].map(i=>form.elements['scheduleCycles'+i].value);oldBox.outerHTML=fields(edition,typeId);if(oldMode==='custom'&&form.querySelector('[data-schedule-fields]').dataset.stageNames===oldNames){form.querySelector('[name=scheduleMode][value=custom]').checked=true;[0,1,2].forEach(i=>form.elements['scheduleCycles'+i].value=oldValues[i]);}custom=null;}else if(event.target.name==='scheduleMode'){if(event.target.value==='standard')custom=[0,1,2].map(i=>form.elements['scheduleCycles'+i].value);else if(custom)[0,1,2].forEach(i=>form.elements['scheduleCycles'+i].value=custom[i]);}sync();window.UKI18n?.refresh(form);});form.addEventListener('input',event=>{if(event.target.name?.startsWith('scheduleCycles'))sync();});sync();}
function panel(c){const s=info(c),editable=canEdit(c)&&c.phase!=='Closed';if(!s)return `<div class="csp-panel csp-unconfigured"><span>${L('Cycle progression is not configured. Existing records are kept as written.','진행 방식 미설정 · 기존 기록을 그대로 유지합니다.')}</span>${button('configure','Set progression','진행 방식 설정',c,!editable)}</div>`;const stage=L(s.stage.name,names[s.stage.name]||s.stage.name),past=(s.plan.history||[]).filter(h=>!h.undoneAt).at(-1),undo=!!past&&past.toCycle===s.cycle&&past.finishedAfter===s.complete;return `<section class="csp-panel"><div class="csp-current"><small>${s.plan.mode==='standard'?L('Fixed standard structure','일반 구성 고정'):L('Custom cycle counts','커스텀 사이클 구성')}</small><strong>${s.complete?L('Schedule complete','일정 완료'):stage+` ${s.stageCycle} / ${s.stage.cycles}`}</strong><span>${L('Overall cycle','전체 사이클')} ${s.cycle} / ${s.total}</span></div><div class="csp-track" aria-label="Campaign stages" data-i18n-ko-aria-label="캠페인 단계">${s.plan.stages.map(p=>`<span class="${p===s.stage?'is-current':''}">${L(p.name,names[p.name]||p.name)} ${p.cycles}</span>`).join('<span aria-hidden="true">→</span>')}</div><div class="actions">${s.complete?button('triumphs','View Triumphs','트라이엄프 확인',c):button('advance',s.cycle===s.total?'Complete schedule':'Next cycle',s.cycle===s.total?'일정 완료':'다음 사이클',c,!editable||s.outOfRange)}${button('undo','Undo last step','마지막 진행 취소',c,!editable||!undo)}${button('configure','Edit progression','진행 방식 수정',c,!editable)}</div></section>`;}
function button(action,en,ko,c,disabled=false){return `<button type="button" class="btn small" data-campaign-schedule="${action}" data-campaign-id="${E(c.id)}" ${disabled?'disabled':''}>${L(en,ko)}</button>`;}
function dialogLabels(en,ko,submitEn,submitKo){for(const [selector,a,b]of [['.modal-head h2',en,ko],['#modal-submit',submitEn,submitKo]]){const node=document.querySelector(selector);if(node){node.dataset.i18nEn=a;node.dataset.i18nKo=b;node.textContent=T(a,b);}}}
function configure(c){if(window.MMCampaignQuickFlow)return MMCampaignQuickFlow.configure(c);if(!canEdit(c))return;const existing=c.campaignSchedule,cycle=positive(c.currentCycle)?Number(c.currentCycle):1;cpModal('Campaign progression',fields(c.edition,c.campaignTypeId,c)+`<p class="wide muted">${L('The current cycle and existing battle records are retained. Changing a plan does not grant income, XP or downtime rewards.','현재 사이클과 기존 전투 기록은 유지합니다. 진행 방식을 바꿔도 수입·XP·다운타임 보상을 지급하지 않습니다.')} · ${L('Current cycle','현재 사이클')}: ${cycle}</p>`,'Save Changes',()=>{if(!canEdit(c)||!data.campaigns.includes(c))return false;const result=read(document.querySelector('#modal-form'),c.edition,typeFor(c));if(result.error){cpMessage(result.error);return false;}if(result.value.stages.reduce((n,s)=>n+s.cycles,0)<cycle){cpMessage(T('The plan must include the current recorded cycle.','계획의 전체 사이클 수가 현재 기록된 사이클 이상이어야 합니다.'));return false;}c.campaignSchedule={...result.value,history:existing?.history||[],completed:!!existing?.completed&&cycle===result.value.stages.reduce((n,s)=>n+s.cycles,0)};c.currentCycle=cycle;cpActivity(c,'Campaign progression configured: '+c.campaignSchedule.mode);save();});bind(document.querySelector('#modal-form'),()=>({edition:c.edition,typeId:typeFor(c)}));dialogLabels('Campaign progression','캠페인 진행 방식','Save Changes','변경 사항 저장');window.UKI18n?.refresh();}
function advance(c,override=false){if(window.MMCampaignQuickFlow)return MMCampaignQuickFlow.advance(c,override).catch(error=>window.MMCampaignAutomation?.notify(error.message,true));const s=info(c);if(!canEdit(c)||c.phase==='Closed'||!s||s.complete||s.outOfRange||!data.campaigns.includes(c))return;const pendingBattles=(c.battles||[]).filter(b=>Number(b.cycle)===s.cycle&&b.challenge&&b.status!=='Played'),pendingSessions=(c.sessions||[]).filter(b=>!['Completed','Cancelled'].includes(b.status)&&(!b.cycle||Number(b.cycle)===s.cycle));if(!override&&(pendingBattles.length||pendingSessions.length)){cpModal('Unfinished cycle records',`<p class="wide">${L('Unresolved challenges','미해결 도전')}: ${pendingBattles.length} · ${L('Open sessions','진행 중인 전투')}: ${pendingSessions.length}</p><p class="wide muted">${L('Resolve these first, or explicitly carry them over. Advancing does not complete their results.','먼저 처리하거나 보류 상태로 넘기세요. 사이클을 넘겨도 전투 결과가 자동 완료되지는 않습니다.')}</p>${cpCheck('carryOver',L('I reviewed these records and will carry them over.','이 기록을 확인했으며 미완료 상태로 보류합니다.'))}`,'Next cycle',v=>{if(info(c)?.cycle!==s.cycle||c.campaignSchedule!==s.plan){cpMessage(T('The current cycle changed. Reopen progression.','현재 사이클이 변경되었습니다. 진행 화면을 다시 여세요.'));return false;}if(v.carryOver!=='yes'){cpMessage(T('Confirm the carry-over decision.','미완료 기록의 보류를 확인하세요.'));return false;}advance(c,true);return true;});dialogLabels('Unfinished cycle records','미완료 사이클 기록','Next cycle','다음 사이클');window.UKI18n?.refresh();return;}
 const finished=s.cycle===s.total,to=finished?s.cycle:s.cycle+1;s.plan.history??=[];s.plan.history.push({id:id(),at:now(),fromCycle:s.cycle,toCycle:to,finishedBefore:s.complete,finishedAfter:finished});c.currentCycle=to;s.plan.completed=finished;cpActivity(c,finished?'Campaign schedule completed':`Campaign advanced to cycle ${to}`);save();}
function undo(c){if(window.MMCampaignQuickFlow)return MMCampaignQuickFlow.undo(c).catch(error=>window.MMCampaignAutomation?.notify(error.message,true));const s=info(c),h=s?.plan.history?.filter(h=>!h.undoneAt).at(-1);if(!canEdit(c)||!h||h.toCycle!==s.cycle||h.finishedAfter!==s.complete)return;c.currentCycle=h.fromCycle;s.plan.completed=h.finishedBefore;h.undoneAt=now();cpActivity(c,'Campaign progression step undone');save();}
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-campaign-schedule]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();const c=data.campaigns.find(c=>c.id===b.dataset.campaignId);if(!c)return;const a=b.dataset.campaignSchedule;if(a==='configure')configure(c);if(a==='advance')advance(c);if(a==='undo')undo(c);if(a==='triumphs'){data.campaignTab='triumphs';render();}},true);
window.MMCampaignSchedule={fields,read,bind,panel,info,cycleLimit:c=>info(c)?.total||Number.MAX_SAFE_INTEGER};
})();
